import type { BookChapter } from "../types";

/* The Discover book — topic 1.1 (Understand the Brief & the System) */
export const chapter1: BookChapter = {
  id: "day-1", n: "1", day: 1, title: "Understand the Brief & the System", kicker: "System Context Review",
  question: "What exactly are we being asked for, and what already exists?",
  intro: [
    { t: "p", text: "Topic 1.1 is about the ground you’re standing on. Before you frame a problem or think about a solution, you need two things: a precise understanding of what is being asked for, and an honest picture of what already exists — the code, the data, the integrations and their limits." },
    { t: "p", text: "The job of this topic, in one line: *when I’m handed a brief, help me understand it and the system behind it well enough that I never design around a guess.*" },
    { t: "p", text: "This topic runs as one process — **Understand the Brief & the System** — in four lessons. Each one hands its output to the next, and questions are logged all the way through. Integration mapping can start while the code audit finishes; the rest runs in order." },
    { t: "figure", fig: { kind: "tree", root: "1.1 Understand the Brief & the System", children: [{ label: "1.1.1 Read the Brief", text: "2–4 hours", children: [{ label: "Technical brief summary" }, { label: "Technical question log" }] }, { label: "1.1.2 Audit the System", text: "½–1 day", children: [{ label: "System audit" }, { label: "System context diagram" }] }, { label: "1.1.3 Map Data & Integrations", text: "½–1 day", children: [{ label: "Data flow map" }, { label: "Integration inventory" }] }, { label: "1.1.4 Log Constraints & Assumptions", text: "2–4 hours", children: [{ label: "Technical constraint log" }, { label: "System context pack" }] }] }, caption: "The topic broken into its four lessons and the two outputs each one hands on. Notice that the last output, the system context pack, gathers all the others." },
    { t: "table", caption: "The four lessons of topic 1.1 and what each one hands on", head: ["Lesson", "What you do", "What it produces", "Timebox"], rows: [
      ["1.1.1 Read the Brief as an Engineer", "Restate the ask, map inputs, outputs and volumes, log every unknown", "Technical brief summary · Technical question log", "2–4 hours"],
      ["1.1.2 Audit the Current System & Codebase", "Run it, follow one real transaction, draw the context, measure health", "System audit · System context diagram", "½–1 day"],
      ["1.1.3 Map Data, Integrations & Dependencies", "Trace every data flow, list every integration, prove each with a test call", "Data flow map · Integration inventory", "½–1 day"],
      ["1.1.4 Log Technical Constraints & Assumptions", "Separate facts from guesses, confirm hard limits, assemble the pack", "Technical constraint log · System context pack", "2–4 hours"],
    ] },
    { t: "figure", fig: { kind: "trace", from: "REQ", to: "C/A" }, caption: "The stretch of the trace chain topic 1.1 creates: the request (REQ) leads to questions (Q), system elements (SYS), data flows (DF), integrations (INT) and constraints and assumptions (C/A) — each with an ID later work can point at." },
    { t: "p", text: "Two rules hold for the whole topic. **No solutioning** — you are finding out, not designing. And **read-only, test environments only** — you change nothing while you audit, and you never make a test call against production." },
    { t: "p", text: "The topic closes at the **System Context Review**. The tech lead accepts the system context pack when four things are true: the ask is restated without technology; every component has an ID and a version; every integration has its interface, auth, limits and owner; and every constraint has a source. If the code contradicts the brief, you go back to the brief. If an integration limit has no source, you go back to the integrations. If there is no access to the system, the tech lead escalates. And if there is nothing technical to build at all, you stop and say so — that is a result, not a failure." },
    { t: "figure", fig: { kind: "hub", center: "Pack accepted when…", items: [{ label: "Ask without technology", icon: "flag", text: "The ask is restated without naming any technology." }, { label: "IDs and versions", icon: "label", text: "Every component has an ID and a version." }, { label: "Integrations described", icon: "integration_instructions", text: "Every integration has its interface, auth, limits and owner." }, { label: "Sourced constraints", icon: "verified", text: "Every constraint has a source." }] }, caption: "The four things the tech lead checks at the System Context Review. If any one is missing, the pack goes back." },
    { t: "figure", fig: { kind: "decide", start: "contra", nodes: [{ id: "contra", q: "Does the code contradict the brief?", yes: "brief", no: "src" }, { id: "brief", result: "Go back to the brief", tone: "neutral" }, { id: "src", q: "Does every integration limit have a source?", yes: "acc", no: "ints" }, { id: "ints", result: "Go back to the integrations", tone: "neutral" }, { id: "acc", q: "Is there access to the system?", yes: "tech", no: "esc" }, { id: "esc", result: "The tech lead escalates", tone: "bad" }, { id: "tech", q: "Is there anything technical to build?", yes: "review", no: "stop" }, { id: "stop", result: "Stop and say so — a result, not a failure", tone: "neutral" }, { id: "review", result: "On to the System Context Review", tone: "good" }] }, caption: "The topic’s routes back, as a walk-through. Each “no” sends you to a specific place, and stopping because there is nothing to build is a valid end." },
  ],
  sections: [
    /* ───────────────────────────── 1.1.1 ───────────────────────────── */
    {
      id: "discover.context.brief", fid: "discover.context.brief", code: "1.1.1", title: "Read the Brief as an Engineer", minutes: 15,
      blocks: [
        { t: "lead", text: "A client brief tells you what someone wants to change in their business. Your first job is to turn it into what a system must do — what comes in, what goes out, how much of it — and to write down, plainly, everything nobody has told you yet." },
        { t: "tldr", items: [
          "Restate the ask in one line, in verbs, with no technology in it.",
          "Break it into capabilities, and give every input and output a format.",
          "Every number cites a source or is marked **assumed**.",
          "Every unknown becomes a numbered question with an owner.",
          "No solution or tool is chosen here — a named technology is a client preference.",
        ] },
        { t: "p", text: "The job to be done is simple to say: *help me understand exactly what I’m being asked to build, and what I don’t know yet.* The trap is just as simple: reading the brief, recognising something familiar, and quietly starting to design it." },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Everything downstream is built on this reading. If you misread the brief, you’ll audit the wrong parts of the system, measure the wrong things and compare options against the wrong goal — all very carefully. Careful work on the wrong thing is still the wrong thing." },
        { t: "p", text: "Two risks hide here in particular. The first is **building the wrong thing from a misread brief** — usually because a technology named in the brief was taken as the requirement. The second is **volume or performance needs buried in a sentence nobody underlined**: “doubling at peak”, “before the busy season”, “from all our sites”. Those few words decide whether a design works; if you don’t pull them out now, you meet them in production." },
        { t: "pull", text: "A brief tells you what someone wants. Your summary says what a system must do — and what you still don’t know." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This is the first lesson of the first topic. It takes one input — the **client brief** — and produces two outputs: the **technical brief summary** and the **technical question log**. Both go straight to 1.1.2, where you audit the system the brief is about. The summary tells the audit what to look for; the question log tells it what to find out." },
        { t: "p", text: "It is also where the trace chain starts. The brief is the request, REQ-###. Every open question you log here becomes a Q-## linked to that request, so that later — in a spike, an estimate or a decision record — anyone can see which question a piece of work was answering." },

        { t: "h", text: "What you start with" },
        { t: "p", text: "You need a client brief in writing and a practice project chosen. If the brief arrived as a call or a chat message, write it down first and confirm it with the client — you can’t restate what you can’t point at. You also need a client contact who can answer questions, because most of what you produce in this topic is questions." },
        { t: "table", caption: "Who does what in 1.1.1 (RACI)", head: ["Role", "RACI", "What they do here"], rows: [
          ["Engineer", "R — Responsible", "Reads the brief, writes the summary and the question log, assigns owners"],
          ["Tech lead", "A — Accountable", "Reads the summary back against the brief and accepts it"],
          ["Client contact", "C — Consulted", "Answers questions; settles conflicting requirements"],
          ["Architect", "I — Informed", "Sees the summary before the audit begins"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Technical brief summary", sub: "+ question log" }, around: [{ label: "Engineer", sub: "Responsible", type: "person", dir: "in", link: "Writes it", text: "Reads the brief, writes the summary and the question log, assigns owners." }, { label: "Tech lead", sub: "Accountable", type: "person", dir: "out", link: "Reads it back", text: "Reads the summary back against the brief and accepts it." }, { label: "Client contact", sub: "Consulted", type: "person", dir: "both", link: "Answers questions", text: "Answers questions; settles conflicting requirements." }, { label: "Architect", sub: "Informed", type: "person", dir: "out", link: "Sees it", text: "Sees the summary before the audit begins." }] }, caption: "The RACI around the lesson’s outputs. Only the engineer writes; only the tech lead accepts — the client answers, but doesn’t sign off." },
        { t: "p", text: "The work is timeboxed to **2–4 hours** and closes at the **Brief Understood** gate, with the tech lead’s review notes as evidence. Client material stays in the project workspace." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "The ask is not the solution" },
        { t: "p", text: "Clients often describe what they want in the language of a solution: “use AI to read the orders”, “build an app”, “we need a dashboard”. That is useful information — it tells you what they imagine and what they might be expecting — but it is not the ask. The ask is what must *happen*, stated so that more than one solution could meet it. This is **problem / solution separation**, and it starts here, on the first page of the first topic." },
        { t: "figure", fig: { kind: "split", left: { title: "Client preference — record it", tone: "guess", items: ["“Use AI to read the orders”", "“Build an app for the clerks”", "Kept on the summary as a preference", "Becomes one option later, never deleted"] }, right: { title: "The ask — build to it", tone: "fact", items: ["Says what must happen, in verbs", "Names no tool, product or technique", "Could be met by more than one design", "Another engineer could build the same thing from it"] } }, caption: "Two lines on the summary, never merged. A technology in the brief is kept — as a preference, not as the requirement." },
        { t: "h3", text: "Capabilities are verbs" },
        { t: "p", text: "Once you have the one-line ask, break it into **capabilities**: the things the system must be able to do, numbered, each written as a verb. Receive. Read. Match. Create. Flag. A capability written as a noun (“an order module”) has already started to design something; a capability written as a verb leaves the design open and makes the input and output obvious." },
        { t: "h3", text: "Every input and output has a format" },
        { t: "p", text: "For each capability, write what comes in and what goes out, and in what form: email, PDF attachment, file drop, API call, screen, spreadsheet. Formats matter more than they look. A generated PDF and a scanned PDF are both “a PDF”, and they are completely different problems." },
        { t: "figure", fig: { kind: "hub", center: "Input and output formats", items: [{ label: "Email", icon: "mail", text: "Data that comes in or goes out as an email." }, { label: "PDF attachment", icon: "picture_as_pdf", text: "Generated or scanned — both “a PDF”, two different problems." }, { label: "File drop", icon: "folder_open", text: "Data delivered as a file." }, { label: "API call", icon: "api", text: "One system calling another." }, { label: "Screen", icon: "visibility", text: "Something a person reads or types into." }, { label: "Spreadsheet", icon: "description", text: "Data kept or passed on in a sheet." }] }, caption: "The formats the text names for every input and output. Pin each capability’s input and output to one of these — and say which kind of PDF." },
        { t: "h3", text: "Every number has a source, or says it hasn’t" },
        { t: "p", text: "Put numbers on the work: how many, how often, how big, and what the peak looks like. Where the brief gives a number, write where it came from. Where it doesn’t, write your best estimate and mark it **assumed**. Where two numbers in the brief contradict each other, log both and ask — don’t pick the one you like." },
        { t: "figure", fig: { kind: "decide", start: "given", nodes: [{ id: "given", q: "Does the brief give the number?", yes: "conflict", no: "assumed" }, { id: "conflict", q: "Does it contradict another number in the brief?", yes: "both", no: "source" }, { id: "source", result: "Write it down with where it came from", tone: "good" }, { id: "both", result: "Log both numbers and ask — don’t pick the one you like", tone: "neutral" }, { id: "assumed", result: "Write your best estimate, mark it assumed, and log a question to confirm it", tone: "neutral" }] }, caption: "What to do with each number in the brief. Every path ends with the number either sourced or clearly marked — never quietly chosen." },
        { t: "h3", text: "Every unknown becomes an owned question" },
        { t: "p", text: "The **question backlog** is the habit of turning every gap into a numbered row — Q-01, Q-02 — with its area, why it matters, and who can answer it. A question in a paragraph gets lost; a question in a log gets answered. And a question without an owner is a question nobody answers." },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "Q-01", label: "ID" }, { text: " · How does the ERP accept orders — API, file drop or database?", label: "Question" }, { text: " · Integration", label: "Area" }, { text: " · Decides the whole integration approach", label: "Why it matters" }, { text: " · ERP admin", label: "Owner", note: "A named person or source — not “the client”." }] }, caption: "One row of the question log, taken apart. Each part has a job; drop the owner and the question goes unanswered." },
        { t: "figure", fig: { kind: "knowledge", name: "Brief decomposition" }, caption: "Brief decomposition: from one paragraph of intent to the ask, capabilities, inputs and outputs, volumes, scope and questions." },
        { t: "terms", items: [
          { term: "The ask", def: "One line saying what the system must achieve, in verbs, with no technology named. “Turn … into … without …” is a good shape." },
          { term: "Capability", def: "Something the system must be able to do, written as a numbered verb with an input and an output." },
          { term: "Client preference", def: "A technology or approach named in the brief. Recorded, kept, and treated as one possible option — not the requirement." },
          { term: "Volume", def: "How many, how often, how big, and the peak. Each one either cites a source or is marked assumed." },
          { term: "Technical question log", def: "The numbered list of everything the brief leaves open (Q-##), each with an area, why it matters and an owner." },
          { term: "Read-back", def: "The tech lead reading your summary against the original brief to check you haven’t missed, misread or solved anything." },
        ] },

        { t: "h", text: "How to do it" },
        { t: "p", text: "The workflow has five steps and one decision. Questions are logged while you restate the brief, not after — the moment you notice a gap, write it down." },
        { t: "steps", items: [
          { title: "Restate the ask and its capabilities", text: "Write one line that says what the system must achieve — in verbs, with no technology in it. A useful shape is “Turn X into Y without Z.” Then break it into capabilities: the things it must be able to do, numbered and written as verbs. If the brief names a technology, put it in a separate line marked **client preference**. If you can’t write the one-line ask without guessing what the core function is, that is the finding — stop and ask the client before going further.", tip: "Test your one-liner: could two different engineers meet it with two different designs? If not, a solution has crept in." },
          { title: "Map inputs, outputs and volumes", text: "For every capability, write what comes in and what goes out, with its format. List the users who touch the system and what they do. Then put numbers on it — counts, frequency, size, peaks — with the source next to each, or the word **assumed**. Finish with an explicit in-scope / out-of-scope list: drawing the edge now saves an argument later.", tip: "Watch for volume words without numbers: “peak season”, “all sites”, “growing fast”. Each one is either a number with a source or a question." },
          { title: "Log the open technical questions", text: "Every gap becomes a row in the question log: a Q-## ID, the question, its area (data, integration, performance, security, infrastructure, code), why it matters and who could answer it. Mark any question that only a spike or prototype can answer — you’ll plan those in topic 1.2. Don’t answer the questions yet, and don’t bury them in the summary’s prose." },
          { title: "Decide: is the brief understood?", text: "Read your summary back against the brief, then take it to the tech lead for a read-back. The test is simple: could another engineer build the same thing from this summary? If there are gaps, re-read and restate. If the ask conflicts with a hard limit, the tech lead takes it to the client. If there’s nothing technical to build at all — the real fix is a process or policy change — stop and say so, and record it in the learning log." },
          { title: "Give every question an owner", text: "Each question gets a person or a source who can answer it and, where it matters, a date. Flag the questions that block the next lesson’s work — the audit — so they’re chased first. Assign every question before the review closes; an unowned question is a guess waiting to happen.", tip: "“The client” is not an owner. Name the person: the ERP admin, the order-clerk lead, IT." },
        ] },
        { t: "figure", fig: { kind: "workflow", fid: "discover.context.brief" }, caption: "The Read the Brief workflow — restate, map, log, decide, own. The loops show where you go when the brief isn’t understood yet: back to restate, to the client, or to a stop." },
        { t: "callout", tone: "warn", title: "The rule for this step", text: "No solution or tool is chosen here. When the brief names a technology — “use AI”, “build an app” — record it as a client preference, not as the ask." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "Northwind’s clerks re-type emailed PDF orders into the ERP, and the brief lands with the engineering team ahead of peak season. In the client’s words: “We keep re-typing orders from email into the ERP — can you automate it before peak season?”" },
        { t: "figure", fig: { kind: "template", id: "client-brief" }, caption: "Northwind’s client brief — what they asked for, what happens today, the numbers they gave and the limits they mentioned. This is your only input here." },
        { t: "p", text: "The brief says what happens today: PDF orders land in a shared inbox, and four clerks re-type each line into the ERP and email a confirmation. It gives numbers — about 14 minutes an order, about 6 hours a day of re-typing, 3% of orders with entry errors — and limits: the ERP can’t be replaced this year, customer data stays in-country, and there is no new headcount." },
        { t: "figure", fig: { kind: "hub", center: "Northwind’s brief", items: [{ label: "~14 minutes an order", icon: "timer", text: "Time a clerk spends re-typing one order today." }, { label: "~6 hours a day", icon: "schedule", text: "Re-typing across the clerks, every day." }, { label: "3% entry errors", icon: "error", text: "Share of orders with entry errors." }, { label: "ERP stays this year", icon: "lock", text: "The ERP can’t be replaced this year." }, { label: "Data stays in-country", icon: "policy", text: "Customer data stays in-country." }, { label: "No new headcount", icon: "groups", text: "The fix can’t add people." }] }, caption: "The numbers and limits the brief gives, in one place. The first three describe the pain; the last three fence in every possible answer." },
        { t: "p", text: "The engineer restates the ask: **turn emailed PDF orders into ERP sales orders without a clerk re-typing them.** No tool is named. The word “automate” in the brief tells you the client wants less manual work; it doesn’t tell you how." },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "Turn " }, { text: "emailed PDF orders", label: "What comes in" }, { text: " into " }, { text: "ERP sales orders", label: "What must come out" }, { text: " without " }, { text: "a clerk re-typing them", label: "What must stop", note: "“Automate” says the client wants less manual work — not how." }, { text: "." }] }, caption: "Northwind’s one-line ask in the “Turn X into Y without Z” shape. No tool appears in any part, so more than one design could meet it." },
        { t: "table", caption: "Northwind’s technical brief summary (REQ-014), from the template’s example", head: ["Part", "What the engineer wrote"], rows: [
          ["The ask", "Turn emailed PDF orders into ERP sales orders without a clerk re-typing them."],
          ["Capabilities", "1 Receive orders from the shared inbox · 2 Read customer, lines, quantities and dates from the PDF · 3 Match the customer code · 4 Create the order in the ERP · 5 Flag anything it isn’t sure of for a clerk"],
          ["Inputs", "Email + PDF attachment (scanned or generated)"],
          ["Outputs", "ERP sales order (import API, JSON) · confirmation email · exception item for a clerk"],
          ["Users and volumes", "4 clerks; ~1,140 orders in two weeks (inbox sample), doubling at peak; 1–40 lines an order"],
          ["In scope", "Email PDF orders, EU sites"],
          ["Out of scope", "EDI customers, phone orders, ERP changes"],
          ["What “working” means", "Order created correctly without re-typing; clerk time per order falls; no order lost or duplicated"],
          ["Open questions", "Q-01 … Q-07, in the question log"],
        ] },
        { t: "figure", fig: { kind: "tree", root: "REQ-014: emailed PDF orders → ERP sales orders", children: [{ label: "1 Receive", text: "Orders from the shared inbox — email + PDF attachment" }, { label: "2 Read", text: "Customer, lines, quantities and dates from the PDF — scanned or generated" }, { label: "3 Match", text: "The customer code" }, { label: "4 Create", text: "The order in the ERP — import API, JSON" }, { label: "5 Flag", text: "Anything it isn’t sure of — an exception item for a clerk" }] }, caption: "The ask broken into its five capabilities, each a verb with its input or output. Capability 5 keeps a person in the loop without choosing any design." },
        { t: "figure", fig: { kind: "bars", unit: "orders in two weeks", rows: [
          { label: "Inbox sample (two weeks)", value: 1140, max: 2400, tone: "neutral", note: "Counted from the inbox — sourced" },
          { label: "Peak (doubling)", value: 2280, max: 2400, tone: "bad", note: "“Doubling at peak” from the brief — confirm the figure" },
        ] }, caption: "The volume line that a quick reading skips: ~1,140 orders in a two-week inbox sample, and the brief says it doubles at peak. Whatever is built must be sized for the second bar, not the first." },
        { t: "p", text: "Notice two things in that summary. The input says “scanned or generated” — the engineer has already spotted that “a PDF” is two different problems. And the outputs include an *exception item for a clerk*: capability 5 says the system must flag what it isn’t sure of, which means a person stays in the loop. Neither of those choices is a design; both are things any design will have to handle." },
        { t: "table", caption: "The first rows of Northwind’s technical question log", head: ["Q ID", "Question", "Area", "Why it matters", "Who can answer", "Status"], rows: [
          ["Q-01", "How does the ERP accept orders — API, file drop or database?", "Integration", "Decides the whole integration approach", "ERP admin", "Answered: REST import API only (ERP admin guide §7)"],
          ["Q-02", "What share of PDFs are scans vs generated?", "Data", "Scans need OCR — accuracy risk", "Inbox sample", "Needs a spike"],
          ["Q-03", "Where do customer codes live?", "Data", "Matching needs a trusted source", "Order-clerk lead", "Open"],
        ] },
        { t: "p", text: "The engineer logs Q-01 to Q-07; the first three are shown above. The tech lead reads the summary back against the brief and accepts it. The summary and the question log go on to the audit." },
        { t: "figure", fig: { kind: "template", id: "technical-brief" }, caption: "The technical brief summary — the one-line ask, capabilities, inputs and outputs, volumes, scope and what “working” means. What you hand to the next lesson." },
        { t: "contrast", label: "Restating the ask", bad: { title: "Copies the brief’s solution", text: "“Build an AI tool that reads PDF orders and puts them in the ERP.” A tool has been chosen before anything is understood, and nothing says what “puts them in” means or what happens when it’s unsure." }, good: { title: "Says what must happen", text: "“Turn emailed PDF orders into ERP sales orders without a clerk re-typing them.” Then five numbered capabilities — receive, read, match, create, flag — each with its input and output format. “AI” is recorded as a client preference." } },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "A coding agent is good at this lesson’s first draft: it reads fast, it’s happy to list things, and it doesn’t get bored writing question rows. It is also prone to the two exact failures this lesson exists to prevent — it likes to propose a solution, and it likes to fill a gap with a plausible number. You drive; it drafts; you check; the tech lead decides." },
        { t: "prompt", title: "Restate the brief and map it", text: "Read the client brief I’ve pasted below.\n1. Restate the ask in one sentence a developer would write — what must happen, with no technology named.\n2. List the capabilities it implies as numbered verbs.\n3. If the brief names a technology, record it separately as a client preference.\n4. List every input and output with its format (email, PDF, API call, file, screen…), the users who touch the system, and the volumes and peaks. Put the source next to every number, or mark it ‘assumed’.\n5. End with an in-scope / out-of-scope list.\nDo not propose a solution. Ask me instead of guessing.\n\n[paste brief]" },
        { t: "p", text: "Check its answer before you use a word of it. Is there a technology, product or technique anywhere in the one-line ask? Is every capability a verb? Is there any number without a source or an “assumed” tag — and did any number appear that isn’t in the brief at all? Did it quietly drop a limit the client mentioned?" },
        { t: "prompt", title: "Turn the gaps into an owned question log", text: "List every technical question this brief leaves open, as rows for my question log: Q-## ID, the question, its area (data, integration, performance, security, infrastructure, code), why it matters, and who could answer it. Mark any that only a spike or prototype can answer. Then compare my technical brief summary (pasted below) with the original brief and point out anything I missed, misread or quietly turned into a solution.\n\n[paste summary]" },
        { t: "p", text: "Check: does every question name a real person or source as its owner, not “the client”? Are any of its “questions” really disguised answers (“Should we use OCR?”)? Rewrite those as what you need to know (“What share of PDFs are scans?”). And remember the agent’s comparison is a draft of the read-back — the tech lead still does the real one." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Tech lead"], steps: [{ lane: 0, label: "Paste the brief" }, { lane: 1, label: "Restate, list capabilities, map volumes", sub: "A draft" }, { lane: 0, label: "Check the draft", sub: "Technology in the ask? Unsourced numbers?" }, { lane: 1, label: "Draft the question log; compare with the brief" }, { lane: 0, label: "Name real owners; rewrite disguised answers", sub: "“Should we use OCR?” → “What share are scans?”", flag: "manual" }, { lane: 2, label: "Real read-back and acceptance", flag: "ok" }] }, caption: "Who does what when an agent helps with 1.1.1. The agent drafts twice, you check both times, and only the tech lead’s read-back counts." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Paste the brief and ask your agent to restate the ask in verbs, list capabilities with inputs, outputs and formats, and turn every gap into a numbered question. Then check its work: did it sneak a technology into the ask? Did it invent a volume instead of marking it assumed?" },

        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "The summary copies the brief instead of restating it.", fix: "Rewrite each capability as a verb with an input and an output. If a sentence could be pasted back into the brief unchanged, it hasn’t been restated." },
          { trap: "A technology in the brief becomes the ask.", fix: "Move it to a separate line marked client preference. Keep it — it becomes one option in topic 1.4 — but don’t build to it." },
          { trap: "Volumes are written without sources.", fix: "Every number cites where it came from, or says assumed and gets a question to confirm it." },
          { trap: "Contradictory numbers are quietly reconciled.", fix: "Log both numbers and ask. The client settles conflicting requirements, not you." },
          { trap: "Questions are logged without owners.", fix: "Assign every question before the review closes — a named person or source, and a date where it matters." },
          { trap: "Questions are answered by assumption to keep moving.", fix: "Leave them open. An answered-by-guess question is worse than an open one, because nobody will look at it again." },
        ] },
        { t: "figure", fig: { kind: "fishbone", effect: "A brief misread or guessed", bones: [{ label: "Restating", causes: ["Summary copies the brief", "A technology becomes the ask"] }, { label: "Numbers", causes: ["Volumes without sources", "Contradictions quietly reconciled"] }, { label: "Questions", causes: ["Logged without owners", "Answered by assumption"] }] }, caption: "The six common mistakes, grouped by where they happen. Each one leaves a guess where the summary should hold a fact or a question." },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of 1.1.1", head: ["Situation", "What you do"], rows: [
          ["Tech lead finds gaps at the read-back", "Rework — re-read the brief and restate"],
          ["The brief names a technology", "Record it as a client preference, not the ask"],
          ["Numbers in the brief contradict each other", "Log both and ask the client"],
          ["The brief arrives as a call or a chat", "Write it down and confirm it with the client first"],
          ["The brief contradicts a hard limit", "Escalate — the tech lead takes it to the client"],
          ["The core function can’t be restated without guessing", "Failure — stop and get the client to clarify before going on"],
          ["Nothing technical to build (a process or policy fix)", "Stop and say so — recorded in the learning log"],
          ["Small, well-specified change", "Summary and questions on one page"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "written", nodes: [{ id: "written", q: "Is the brief in writing?", yes: "restate", no: "writeit" }, { id: "writeit", result: "Write it down and confirm it with the client first", tone: "neutral" }, { id: "restate", q: "Can you restate the core function without guessing?", yes: "tech", no: "fail" }, { id: "fail", result: "Failure — stop and get the client to clarify before going on", tone: "bad" }, { id: "tech", q: "Is there anything technical to build?", yes: "limit", no: "stopsay" }, { id: "stopsay", result: "Stop and say so — recorded in the learning log", tone: "neutral" }, { id: "limit", q: "Does the brief contradict a hard limit?", yes: "esc", no: "readback" }, { id: "esc", result: "Escalate — the tech lead takes it to the client", tone: "neutral" }, { id: "readback", q: "Does the tech lead find gaps at the read-back?", yes: "rework", no: "ok" }, { id: "rework", result: "Rework — re-read the brief and restate", tone: "bad" }, { id: "ok", result: "Brief understood — summary and question log go to the audit", tone: "good" }] }, caption: "The routes out of 1.1.1 as a walk-through. The client clarifies, the tech lead escalates, and you decide only whether to stop and say so." },
        { t: "callout", tone: "tip", title: "Stopping is a result", text: "If the honest reading is that nothing needs building — a policy change or a better process would do it — saying so in the first topic saves everyone weeks. Record it in the learning log, with the reasons." },

        { t: "h", text: "What good looks like" },
        { t: "p", text: "A good summary is short, specific and boring in the best way: another engineer could read it and build the same thing you would. Its questions are sharp and owned. Its numbers can be checked. And there is nothing in it that a solution would have to be — only what a solution must do." },
        { t: "good", items: ["The ask is stated without any technology", "Every input and output has a format", "Every volume cites a source or is marked assumed", "Every open question has an owner"] },
        { t: "checklist", title: "Before you move on", items: [
          "The one-line ask names no tool, product or technique",
          "Capabilities are numbered verbs, each with an input and an output",
          "Every input and output has a format",
          "Every number has a source or is marked assumed",
          "In scope and out of scope are both written down",
          "Every question has a Q-## ID, an area and a named owner",
          "Questions that block the audit are flagged",
          "The tech lead has read the summary back and accepted it",
        ] },
        { t: "try", text: "Write the technical brief summary for the order-intake case: the one-line ask, five capabilities, inputs and outputs with formats, and three questions with owners. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.1.2 ───────────────────────────── */
    {
      id: "discover.context.system", fid: "discover.context.system", code: "1.1.2", title: "Audit the Current System & Codebase", minutes: 14,
      blocks: [
        { t: "lead", text: "Almost nothing is built on empty ground. This lesson finds out what really exists — by running it and reading it — so that you don’t design around a system that only lives in the documentation." },
        { t: "tldr", items: [
          "Get access and run the system before you judge it.",
          "Follow one real transaction from entry to storage — not the folder tree.",
          "Draw a C4 context diagram; every component gets an ID and a version.",
          "Report code health as numbers, never adjectives.",
          "Read-only: change nothing while auditing; security findings go to their owner the same day.",
        ] },
        { t: "p", text: "There is a system already — sometimes a large one, sometimes a spreadsheet and a habit — and whatever you build will live beside it, inside it or on top of it. The documentation describes the system someone meant to build. Only running it shows you the one that’s there." },
        { t: "p", text: "The job: *help me know what I’m building on, so I don’t design around a system that doesn’t exist.*" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Two risks live here. The first is **designing around a system that doesn’t exist** — the documented version, the one in someone’s memory, the one before last year’s patch. The second is **debt that blocks new work**: no tests, no build pipeline, secrets in config. Neither shows up in a meeting; both show up in week three." },
        { t: "figure", fig: { kind: "fishbone", effect: "Problems that surface in week three", bones: [{ label: "A system that doesn’t exist", causes: ["The documented version", "The one in someone’s memory", "The one before last year’s patch"] }, { label: "Debt that blocks new work", causes: ["No tests", "No build pipeline", "Secrets in config"] }] }, caption: "The two risks the audit exists to catch. Neither shows up in a meeting — only running and reading the system brings them out." },
        { t: "p", text: "An audit also settles a question that shapes every option you’ll compare later: can new work safely build *on* this system, should it sit *beside* it, or is the system being *replaced* anyway? You can’t answer that from a wiki page. You answer it from a running system and a measured codebase." },
        { t: "pull", text: "The documentation describes the system someone meant to build. Only running it shows you the one that’s there." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "The audit takes the **technical brief summary** from 1.1.1 — which tells you which part of the system matters — and produces the **system audit** and the **system context diagram**. Both go to 1.1.3, where you trace the data and integrations that cross the boundary you’ve just drawn. Each component you find gets a SYS-## ID linked to the request, so later work can point at exactly the part it touches." },
        { t: "p", text: "If what you find in the code contradicts the brief — the brief says orders arrive one way, the code shows another — that’s a loop back to 1.1.1, not something to smooth over." },

        { t: "h", text: "What you start with" },
        { t: "table", caption: "Inputs and outputs", head: ["In", "Out"], rows: [
          ["Technical brief summary (accepted)", "System audit — components, stack, build, code health, debt, operations, verdict"],
          ["Repository & environment access (read-only)", "System context diagram — C4 level 1"],
          ["System documentation (whatever exists, with its age)", "Tech lead review notes"],
        ] },
        { t: "table", caption: "Who does what in 1.1.2 (RACI)", head: ["Role", "RACI", "What they do here"], rows: [
          ["Engineer", "R — Responsible", "Gets access, runs the system, traces, draws, measures"],
          ["Tech lead", "A — Accountable", "Reviews the audit and accepts it"],
          ["Architect", "C — Consulted", "Agrees the context diagram"],
          ["System owner", "C — Consulted", "Explains what the code doesn’t; confirms versions"],
          ["Security", "I — Informed", "Receives any security finding — the same day — and owns it"],
        ] },
        { t: "p", text: "Ask for access early: repositories, a test or staging environment, documentation, and read-only logs and monitoring. The timebox is half a day to a day, and waiting for access can eat all of it. If access is delayed, audit from the documents — but mark every finding **unverified** until you’ve run or read it yourself." },
        { t: "figure", fig: { kind: "hub", center: "Ask for access early", items: [{ label: "Repositories", icon: "code", text: "The code, read-only." }, { label: "Test or staging environment", icon: "dns", text: "Somewhere to run it — never production." }, { label: "Documentation", icon: "description", text: "Whatever exists, with its age." }, { label: "Logs and monitoring", icon: "monitoring", text: "Read-only." }, { label: "If access is delayed", icon: "schedule", text: "Audit from the documents and mark every finding unverified." }] }, caption: "The four kinds of access to request in this topic, and the fallback if they’re slow. Waiting for access can eat the whole timebox." },
        { t: "figure", fig: { kind: "template", id: "system-access" }, caption: "The access request — repositories, environment, documentation, logs, and who approved what. Your first finding is how long this takes." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Evidence over assertion" },
        { t: "p", text: "Every finding in the audit should come from something you did: you ran it, you read it, you counted it. “The import is handled by the integration layer” is an assertion. “An order enters through X, is validated in Y and written by Z (file paths attached)” is evidence. When you can’t verify a finding, say so in the finding." },
        { t: "h3", text: "Follow a request, not the folder tree" },
        { t: "p", text: "Reading a codebase file by file tells you how it’s organised, not how it works. A **codebase walkthrough** goes: run it, read the build, trace one request, sketch the parts, measure health, note surprises. Tracing one real transaction — one order, one request — from where it arrives to where it’s stored shows you the components that actually matter, including the ones the diagram forgot." },
        { t: "figure", fig: { kind: "knowledge", name: "Codebase walkthrough" }, caption: "The codebase walkthrough: run it, read the build, trace one request, sketch the parts, measure health, note surprises." },
        { t: "h3", text: "The C4 context diagram" },
        { t: "p", text: "The **C4 model** describes software at four zoom levels: context, containers, components and code. Here you draw only the first. A **context diagram** puts the system in scope in the middle as one box with no internal detail, and around it the people and external systems it talks to. Every arrow is named with what flows and how — protocol and format. Mark every trust boundary you cross." },
        { t: "figure", fig: { kind: "knowledge", name: "C4 model" }, caption: "The C4 model: context, containers, components, code. Here you draw the first level — the context." },
        { t: "h3", text: "Code health as numbers" },
        { t: "p", text: "ISO/IEC 25010 names **maintainability** as a quality of software — how easily it can be changed, tested and understood. You can’t measure that with adjectives. Count instead: number of tests and coverage if it’s reported; whether there is a build pipeline; how many build and deploy steps are manual; how far behind each dependency is; known vulnerabilities; TODO and FIXME count; duplicated logic. “The code is a bit messy” isn’t a finding; “9 tests and no CI” is." },
        { t: "figure", fig: { kind: "hub", center: "Code health as numbers", items: [{ label: "Tests and coverage", icon: "science", text: "Number of tests, and coverage if it’s reported." }, { label: "Build pipeline", icon: "sync", text: "Whether there is one." }, { label: "Manual steps", icon: "build", text: "How many build and deploy steps are manual." }, { label: "Dependency age", icon: "trending_down", text: "How far behind each dependency is." }, { label: "Vulnerabilities", icon: "security", text: "Known vulnerabilities." }, { label: "TODO / FIXME", icon: "edit_note", text: "How many there are." }, { label: "Duplicated logic", icon: "compare_arrows", text: "The same logic in more than one place." }] }, caption: "Seven things to count instead of describing. Each can be re-measured later, so you can tell whether the code got better." },
        { t: "h3", text: "Debt has a shape" },
        { t: "p", text: "Not all debt is the same. The **technical debt quadrant** sorts it by whether it was deliberate or inadvertent, and prudent or reckless. You don’t need to classify every item, but it helps to name the three hotspots that would slow new work and why — that is what the next lessons and the eventual decision need." },
        { t: "figure", fig: { kind: "knowledge", name: "Technical debt quadrant" }, caption: "The technical debt quadrant: deliberate or inadvertent, prudent or reckless. Useful for naming why a hotspot exists, not just that it does." },
        { t: "terms", items: [
          { term: "System audit", def: "A record of what exists — access, components and stack, build and deploy, code health, debt, operations and a verdict — from running and reading it." },
          { term: "SYS-##", def: "The ID given to each component, linked to the request. Every component also has a version." },
          { term: "C4 context (level 1)", def: "One box for the system in scope, with the people and external systems around it and every arrow named." },
          { term: "Trust boundary", def: "A line where data passes between parts with different owners or levels of trust — a network edge, a vendor, the internet." },
          { term: "Unverified finding", def: "Something you believe from documents or conversation but haven’t confirmed by running or reading. Marked as such." },
          { term: "Architecture baseline", def: "The agreed picture of what exists — context, structure, qualities, assumptions — that new work starts from." },
        ] },

        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Get access and run the system", text: "Repository, environment, credentials for a test tenant. Read the README, the build files and the dependency manifest, then try to run it locally or in a test environment. Your first finding is whether you can run it at all, and how long it took — that alone tells you a lot about how new work will go. Note where it runs, how it’s deployed, and what logs, monitoring and backups exist.", tip: "Write down “time to first local run”. It’s one of this lesson’s measures, and it’s honest in a way documentation never is." },
          { title: "Follow one real transaction through the code", text: "Pick one real thing the system does that the brief cares about — one order, one request — and follow it from its entry point to where its data is stored and back. List every component, class and external call it passes through, with file paths. This is where you meet the actual components, not the diagram’s, and where you find the duplicated code path nobody mentioned." },
          { title: "Draw the system context", text: "One C4 context diagram: the system in scope in the middle, the people and systems around it, the arrows between them, each labelled with protocol and format. Every component gets an ID and a version. Keeping it as a table (element · type · talks to · how) and as diagram-as-code makes it easy to review and to change. The context diagram and the health measurement can run in parallel." },
          { title: "Measure code health and debt", text: "Put numbers on it: tests and coverage, dependencies and how far behind each is, build and deploy steps, TODO/FIXME count, duplicated logic. Name the three debt hotspots that would slow new work. List any security finding — secrets in config, an exposed endpoint — separately, and report it to the security owner the same day. Don’t fix it.", tip: "If a number isn’t available (no coverage report, say), the finding is that it isn’t available. Don’t estimate it." },
          { title: "Decide: is it safe to build on?", text: "Prepare the call for the tech lead: build on it, build beside it, or replace it — the evidence for each and what must be true first. If findings are still unverified, trace again. A security issue has already gone to its owner. If the system is being replaced anyway, stop auditing its internals and keep only its interfaces in view — recorded in the learning log." },
        ] },
        { t: "figure", fig: { kind: "workflow", fid: "discover.context.system" }, caption: "Audit the Current System — access and run, trace one transaction, draw, measure, decide. The loops: unverified findings go back to tracing; a security issue goes to its owner; a system being replaced keeps only its interfaces." },
        { t: "callout", tone: "warn", title: "Read-only", text: "Change nothing while auditing. No fixes, no clean-ups, no upgrades — even the obvious ones. You’re here to see the system as it is." },
        { t: "h3", text: "When the system isn’t a normal codebase" },
        { t: "p", text: "When the system is a **vendor product with no source code**, you audit what you can reach: its interfaces, configuration and documentation. When the project is **greenfield** — nothing built yet — you audit the systems the new one must sit beside. And when the system can be **neither run nor read**, that’s the finding — and it changes everything after it." },
        { t: "figure", fig: { kind: "decide", start: "vendor", nodes: [{ id: "vendor", q: "Is it a vendor product with no source code?", yes: "vend", no: "green" }, { id: "vend", result: "Audit what you can reach: interfaces, configuration and documentation", tone: "neutral" }, { id: "green", q: "Is it greenfield — nothing built yet?", yes: "beside", no: "rr" }, { id: "beside", result: "Audit the systems the new one must sit beside", tone: "neutral" }, { id: "rr", q: "Can it be run or read?", yes: "normal", no: "finding" }, { id: "normal", result: "Run it, trace one transaction, draw the context, measure health", tone: "good" }, { id: "finding", result: "That is the finding — and it changes everything after it", tone: "bad" }] }, caption: "Choosing what to audit when the system isn’t a normal codebase. There is always something to audit — even if it’s only the fact that nothing can be." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "The engineer gets read access to the erp-extensions repository and an ERP test tenant; access to production logs is requested and not yet granted. Then they run it, and follow one real order through the code." },
        { t: "table", caption: "Northwind’s components (from the system audit)", head: ["ID", "Component", "Stack / version", "Where it runs"], rows: [
          ["SYS-01", "ERP", "v9, vendor product", "On-premises, Windows Server"],
          ["SYS-02", "Shared inbox", "Microsoft 365", "Microsoft 365"],
          ["SYS-03", "erp-extensions", "C# / .NET 6, 14k lines of code", "Deployed to the ERP server"],
          ["SYS-04", "Clerks’ customer-code spreadsheets", "Spreadsheets", "With the clerks"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "Order-intake service", sub: "in scope — beside the ERP" }, around: [{ label: "Customer", type: "person", dir: "both", link: "PDF order by email · confirmation", text: "Sends orders; receives a confirmation email." }, { label: "Order clerk", type: "person", dir: "out", link: "Exception items", text: "Handles what the system isn’t sure of (capability 5)." }, { label: "Shared inbox", sub: "SYS-02 · Microsoft 365", type: "system", dir: "in", link: "Email + PDF" }, { label: "ERP", sub: "SYS-01 · v9, vendor, on-premises", type: "system", dir: "out", link: "REST import API" }, { label: "erp-extensions", sub: "SYS-03 · C# / .NET 6, 14k lines", type: "system", text: "Not extended until it has CI and tests." }, { label: "Customer-code spreadsheets", sub: "SYS-04 · with the clerks", type: "store", dir: "in", link: "Customer codes", text: "Capability 3 depends on it; Q-03 points straight at it." }] }, caption: "Northwind’s components around the work in scope, each with its SYS ID. Notice SYS-04: a spreadsheet is a component, and an audit that listed only software would have missed it." },
        { t: "p", text: "SYS-04 is worth a second look. A spreadsheet is a component: the clerks use it to match customer codes, and capability 3 in the brief — match the customer code — depends on it. An audit that only listed software would have missed it, and Q-03 (“where do customer codes live?”) points straight at it." },
        { t: "table", caption: "Northwind’s code health and operations, as numbers", head: ["Measure", "Finding"], rows: [
          ["Tests", "9 unit tests, no coverage report"],
          ["Build and deploy", "Manual build on a developer laptop; no CI; deploys copied to the ERP server by IT"],
          ["Dependencies", "3 dependencies two major versions behind"],
          ["Docs", "README out of date (2022)"],
          ["Debt hotspot", "Order import code duplicated in two places"],
          ["Security", "Hard-coded ERP credentials in config — reported to security"],
          ["Operations", "ERP logs to local files; no alerting; nightly backup by IT"],
        ] },
        { t: "figure", fig: { kind: "fishbone", effect: "Don’t extend erp-extensions yet", bones: [{ label: "Tests", causes: ["9 unit tests", "No coverage report"] }, { label: "Build and deploy", causes: ["Manual build on a developer laptop", "No CI", "Deploys copied by IT"] }, { label: "Dependencies", causes: ["3 two major versions behind"] }, { label: "Code", causes: ["Order import duplicated in two places"] }, { label: "Security", causes: ["Hard-coded ERP credentials — reported"] }] }, caption: "The measured findings behind the verdict, grouped. Every cause is a number or a fact someone can re-check, not an adjective." },
        { t: "p", text: "The verdict: **build beside it, not inside it** — a separate service calling the import API; don’t extend erp-extensions until it has CI and tests. That verdict doesn’t pick a technology. It says where new work can safely live, and what would have to be true before anything touched the existing code." },
        { t: "figure", fig: { kind: "flow", steps: [
          { label: "Build on it", sub: "Extend erp-extensions", tone: "risk" },
          { label: "Build beside it", sub: "Separate service, calls the import API", tone: "new" },
          { label: "Replace it", sub: "Ruled out — ERP stays this year", tone: "human" },
        ] }, caption: "The three verdicts an audit can reach. Northwind’s evidence — 9 tests, no CI, duplicated import code, and an ERP that can’t be replaced this year — points to building beside it." },
        { t: "figure", fig: { kind: "template", id: "system-audit" }, caption: "The system audit — access, components and stack, build and deploy, code health, debt, operations and a verdict, with numbers." },
        { t: "figure", fig: { kind: "template", id: "system-context-diagram" }, caption: "Northwind’s C4 context as a table: customer, order clerk, the order-intake service in scope, the Microsoft 365 shared inbox and ERP v9 — each with how it talks." },
        { t: "p", text: "The documentation inventory tells its own story: an order process SOP last updated in November 2024 (medium trust) and an ERP integration diagram from June 2023 (low trust). Writing down each document’s age and how far you trust it is part of the audit — it tells the next person where the paper and the running system are likely to disagree." },
        { t: "contrast", label: "Reporting code health", bad: { title: "Adjectives", text: "“The extension code is a bit old and not very well tested. Deployment is fairly manual.” Nobody can check it, compare it, or tell whether it got better." }, good: { title: "Numbers", text: "“9 unit tests, no coverage report; no CI, manual build on a developer laptop; 3 dependencies two major versions behind; order import duplicated in two places.” Every line can be checked and re-measured." } },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Agents are very good at reading a codebase fast — faster than you. Use that. But an agent reading code can describe a path the system never takes: dead code, a feature flag that’s off, a config value overridden at deploy. Its reading is a map; your run is the territory." },
        { t: "prompt", title: "Get it running, then follow one request", text: "I have read access to this repository. Do not change any file.\n1. Read the README, build files and dependency manifest, and give me the exact steps to run it locally or in a test environment. List anything that blocks running it.\n2. Then follow one real transaction — [describe it, e.g. one incoming order] — from its entry point to where data is stored and back. List every component, class and external call it passes through, with file paths. Don’t summarise the folder tree; follow the request.\nMark anything you inferred rather than read." },
        { t: "p", text: "Check: run the steps yourself — did they work? Open each file path it gave and confirm the call really happens. Is there a second path that does the same thing (duplicated logic often hides here)? Anything it marked as inferred stays **unverified** in your audit until you’ve seen it." },
        { t: "prompt", title: "Draw the context and measure health", text: "Draw a C4 level-1 context diagram as a table (element · type · talks to · protocol / format) for this system and everything around it: people, the system in scope, and every external system. Mark every trust boundary. Then give it to me as Mermaid.\nThen measure the code’s health with numbers: test count and coverage if available, each dependency and how far behind it is, build and deploy steps, TODO/FIXME count, duplicated logic. List the three debt hotspots that would slow new work, and any security finding (e.g. secrets in config) separately. Do not fix anything." },
        { t: "p", text: "Check: does every element have an ID and a version? Is every number something you can reproduce — run the tests, count the dependencies? Did it describe health with adjectives anywhere? Is any security finding on its own list, ready to go to the security owner the same day?" },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Security owner"], steps: [{ lane: 1, label: "Give run steps and blockers", sub: "From README, build files, manifest" }, { lane: 0, label: "Run the steps yourself" }, { lane: 1, label: "Follow one transaction, with file paths", sub: "Marks what it inferred" }, { lane: 0, label: "Open each path; confirm the call happens", sub: "Inferred stays unverified" }, { lane: 1, label: "Draw the C4 table; measure health", sub: "Security findings listed separately" }, { lane: 0, label: "Reproduce every number" }, { lane: 2, label: "Receives any security finding the same day", flag: "ok" }] }, caption: "The agent reads; you run and verify. Every agent step is followed by one of yours, and security findings leave the audit the same day." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask yours to follow one transaction from entry to storage and list every component it touches, then to count tests, check for a pipeline and list outdated dependencies. Verify each finding yourself by running it — an agent reading code can describe a path the system never takes." },

        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "The audit is written from old documentation.", fix: "Mark each finding verified or unverified, and verify the critical ones by running or reading the system." },
          { trap: "Code health is described with adjectives.", fix: "Replace them with counts: tests, coverage, dependency age, build steps, duplicated logic." },
          { trap: "Reading every file in order.", fix: "Run the system and follow one real request. The folder tree shows organisation, not behaviour." },
          { trap: "Fixing an obvious problem while you’re in there.", fix: "Change nothing. Write it down as a finding. The audit must show the system as it is." },
          { trap: "Saving a security finding for the final report.", fix: "Report it to the security owner the same day. Security owns it from there." },
          { trap: "Only listing software.", fix: "Spreadsheets, shared inboxes and manual steps are components too, if the work passes through them." },
        ] },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of 1.1.2", head: ["Situation", "What you do"], rows: [
          ["Findings are unverified", "Rework — run or read again"],
          ["Security issue found (e.g. secrets in code)", "Escalate to the security owner the same day"],
          ["Access is delayed", "Audit from docs and mark every finding unverified"],
          ["Vendor system with no source code", "Audit its interfaces, configuration and docs"],
          ["Greenfield — nothing built yet", "Audit the neighbouring systems the new one must sit beside"],
          ["The code contradicts the brief", "Back to 1.1.1 to restate"],
          ["The system is being replaced anyway", "Stop auditing internals, keep its interfaces — recorded in the learning log"],
          ["The system can be neither run nor read", "Failure — that is the finding; take it to the tech lead"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "access", nodes: [{ id: "access", q: "Do you have access to the system yet?", yes: "replaced", no: "docs" }, { id: "docs", result: "Audit from the docs and mark every finding unverified", tone: "neutral" }, { id: "replaced", q: "Is the system being replaced anyway?", yes: "ifaces", no: "contra" }, { id: "ifaces", result: "Stop auditing internals, keep its interfaces — learning log", tone: "neutral" }, { id: "contra", q: "Does the code contradict the brief?", yes: "back", no: "sec" }, { id: "back", result: "Back to 1.1.1 to restate", tone: "bad" }, { id: "sec", q: "Did you find a security issue?", yes: "secown", no: "verified" }, { id: "secown", result: "Escalate to the security owner the same day", tone: "bad" }, { id: "verified", q: "Are the findings verified?", yes: "verdict", no: "rework" }, { id: "rework", result: "Rework — run or read again", tone: "bad" }, { id: "verdict", result: "Take the verdict — on, beside or replace — to the tech lead", tone: "good" }] }, caption: "The main routes out of 1.1.2. Security goes to its owner, not into the report; the tech lead decides only once findings are verified." },

        { t: "h", text: "What good looks like" },
        { t: "p", text: "A good audit reads like a lab notebook: what you did, what you saw, what you counted. It ends with a verdict and the conditions attached to it, and it is honest about what it couldn’t check. Where the docs and the running system disagreed goes into the learning log." },
        { t: "good", items: ["Every finding comes from running and reading the system", "Every component has an ID and a version", "Code health is given as numbers", "Nothing was changed during the audit"] },
        { t: "checklist", title: "Before you move on", items: [
          "I ran the system (or recorded why I couldn’t)",
          "I followed one real transaction from entry to storage",
          "Every component has a SYS-## ID and a version",
          "The context diagram names every arrow with protocol and format",
          "Code health is numbers: tests, pipeline, dependency age, build steps",
          "The three debt hotspots are named",
          "Any security finding went to its owner the same day",
          "Unverified findings are marked as such",
          "The verdict — on, beside or replace — has its evidence",
        ] },
        { t: "try", text: "Draw the C4 context for the order-intake case and write three code-health measures you would collect on erp-extensions. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.1.3 ───────────────────────────── */
    {
      id: "discover.context.integrations", fid: "discover.context.integrations", code: "1.1.3", title: "Map Data, Integrations & Dependencies", minutes: 13,
      blocks: [
        { t: "lead", text: "The parts of a system that sink projects are rarely in the middle. They’re at the edges — an API limit nobody mentioned, a feed that arrives once a night, personal data flowing somewhere it shouldn’t. This lesson traces every flow and every dependency, with its real limits." },
        { t: "tldr", items: [
          "Trace where data is created, copied and re-typed — re-typing is a flow too.",
          "Every flow gets an ID with format, frequency, volume and sensitivity.",
          "Every integration gets interface, auth, limits and owner.",
          "Documentation is a claim; a test call is evidence — and never against production.",
          "An unknown limit is written as “unknown” and asked in writing, never copied from elsewhere.",
        ] },
        { t: "p", text: "The job: *help me find the dependencies and data problems that would sink the build if I found them late.* Late is the important word. Every limit you find here is a design input. Every limit you find in week three is a rewrite." },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Two concerns drive this lesson. **Hidden dependency limits** — a rate limit, a payload size, an opening-hours window, a timeout — quietly decide whether a design can work at all. And **personal data moving where it shouldn’t** — to a third-party service, a different country, a log file — can stop a project outright, however well it works." },
        { t: "figure", fig: { kind: "fishbone", effect: "A project sunk late", bones: [{ label: "Hidden dependency limits", causes: ["Rate limit", "Payload size", "Opening-hours window", "Timeout"] }, { label: "Personal data where it shouldn’t be", causes: ["A third-party service", "A different country", "A log file"] }] }, caption: "The two concerns behind this lesson. None of these causes is visible in a brief; you find them by following the data and calling each dependency." },
        { t: "p", text: "Both are invisible in a brief and often invisible in code. You only find them by following the data and by calling each dependency for real." },
        { t: "pull", text: "Documentation is a claim. A test call is evidence." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This lesson takes the **system audit** and **context diagram** from 1.1.2 — the boundary and every arrow crossing it — and fills in what flows along each arrow and what limits each one. It produces the **data flow map** and the **integration inventory**, which go to 1.1.4, where every limit you find becomes a sourced constraint or a tagged assumption." },
        { t: "p", text: "It adds two links to the trace chain: DF-## for each data flow and INT-## for each integration, both linked to the SYS-## components they touch and to the Q-## questions they raise. Data tracing and the integration inventory can run in parallel." },

        { t: "h", text: "What you start with" },
        { t: "table", caption: "Inputs and outputs", head: ["In", "Out"], rows: [
          ["System audit (reviewed)", "Data flow map — DF-## rows: from, to, data, format, frequency, volume, sensitivity, manual or not"],
          ["System context diagram", "Integration inventory — INT-## rows: direction, interface, auth, limits, contract, owner, risk"],
          ["API docs or vendor guides; test credentials", "Test call results (evidence)"],
        ] },
        { t: "table", caption: "Who does what in 1.1.3 (RACI)", head: ["Role", "RACI", "What they do here"], rows: [
          ["Engineer", "R — Responsible", "Traces flows, builds the inventory, makes the test calls"],
          ["Tech lead", "A — Accountable", "Accepts the map; decides whether any dependency blocks"],
          ["System owners", "C — Consulted", "Confirm their interface, limits and auth"],
          ["Privacy officer", "C — Consulted", "Advises on flows that carry personal data"],
          ["Architect", "I — Informed", "Sees the dependencies the design will have to respect"],
        ] },
        { t: "p", text: "The timebox is half a day to a day. You need test credentials for at least one real call per integration; ask for them as soon as you know the integration exists, because they’re often the slowest thing to get." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Data flow diagramming" },
        { t: "p", text: "A data flow diagram has four kinds of element and one kind of line: external entities (rectangles), processes (circles), data stores (parallel lines), flows (arrows labelled with the data) — and trust boundaries as dashed lines. It shows where data is **created**, where it is **copied**, where it is **stored**, and — crucially for most business systems — where a person **re-types** it by hand. Re-typing is a flow too; usually the most important one." },
        { t: "figure", fig: { kind: "knowledge", name: "Data flow diagramming" }, caption: "Data flow diagramming: external entities, processes, stores, labelled flows and trust boundaries." },
        { t: "h3", text: "Data lineage" },
        { t: "p", text: "Where a flow diagram shows the whole picture, **data lineage mapping** follows one piece of data along its life: source, transform, store, destination. It answers questions a diagram can’t — how long a copy is kept, which store is the source of truth, where personal data ends up." },
        { t: "figure", fig: { kind: "knowledge", name: "Data lineage mapping" }, caption: "Data lineage: source, transform, store, destination — one piece of data followed end to end." },
        { t: "h3", text: "API contract review" },
        { t: "p", text: "For every integration, read its real contract — an OpenAPI specification, a vendor guide, or the code that calls it today — and write down five things: the **contract** (link and version), the **auth** (method, who issues credentials), the **limits** (rate, size, timeout — as numbers, or “unknown”), the **errors** (codes, retries, idempotency), and the **proof** (one real call made, with the response). An OpenAPI document, where one exists, gives you the paths, schemas and security schemes in one place." },
        { t: "figure", fig: { kind: "knowledge", name: "API contract review" }, caption: "API contract review: contract, auth, limits, errors and proof — five things to write down for every integration." },
        { t: "h3", text: "Surface unknowns early" },
        { t: "p", text: "Some limits you won’t be able to find. That’s fine — as long as you write **unknown**, ask the owner in writing with a date, and add it to the question log. What’s not fine is filling the gap with a typical limit from a different API. A borrowed number looks exactly like a real one, and nobody will question it again." },
        { t: "figure", fig: { kind: "decide", start: "doc", nodes: [{ id: "doc", q: "Is the limit in the real contract?", yes: "cite", no: "owner" }, { id: "cite", result: "Write the number with its source", tone: "good" }, { id: "owner", q: "Has the owner answered in writing?", yes: "cite2", no: "unk" }, { id: "cite2", result: "Write the number, citing the owner’s written answer", tone: "good" }, { id: "unk", result: "Write “unknown”, ask the owner in writing with a date, add it to the question log", tone: "neutral" }] }, caption: "How a limit gets written down. There is no branch for borrowing a typical number from another API — that path doesn’t exist." },
        { t: "terms", items: [
          { term: "Data flow (DF-##)", def: "One movement of data: from, to, what, format, trigger or frequency, volume, sensitivity, and whether a person does it by hand." },
          { term: "Integration (INT-##)", def: "One system, API or service the solution depends on, with direction, interface, auth, limits, contract, owner and risk." },
          { term: "Sensitivity", def: "Public, internal, personal or confidential. Personal data is flagged wherever it flows." },
          { term: "Rate limit", def: "How many requests a service accepts in a period. Along with payload size and timeout, one of the limits that decides a design." },
          { term: "Idempotency", def: "Whether repeating the same request has the same effect as making it once — vital when retries could create duplicates." },
          { term: "Inferred contract", def: "For an undocumented API: the contract you write down from reading the code that calls it today, marked as inferred." },
        ] },

        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Trace the data through today’s flow", text: "Start where data is born and follow it. Where is it created? Where is it copied? Where is it re-typed by a person? Each flow gets an ID (DF-01, DF-02…) with from, to, what data, format, trigger or frequency, volume and sensitivity, and whether a person does it by hand. Flag every flow that carries personal data, and note where it goes.", tip: "Ask the people who do the work to show you, not tell you. The manual flows are rarely written down anywhere." },
          { title: "List every integration and API", text: "Every system, API and service the solution will depend on gets a row: INT-## ID, direction (in, out, both), interface type (REST, SOAP, file, database, email, queue, manual), auth method and owner. Include the ones you would have to *add* — a parsing service, say — even though nothing is chosen yet. They’re dependencies too, and their limits are unknown." },
          { title: "Review the contracts and make a test call", text: "For each integration, read the real contract and fill in limits (rate, payload size, timeout, opening hours), error responses, idempotency and versioning. Write “unknown” instead of guessing. Then make one real test call per integration in a test environment or sandbox, and record what actually happens — the response, the time it took, any error. An undocumented API isn’t a dead end: read the code that calls it today and log the contract you infer, marked as inferred.", tip: "Keep the test call itself — the request and the response — as evidence. It’s the difference between “the API works” and “here is the API working”." },
          { title: "Decide: are the dependencies clear enough to proceed?", text: "Prepare the call for the tech lead: is any dependency blocking, which are high risk and why, and what would unblock each one. Missing limits or owners send you back to the contract review. A blocking dependency — no access, no API — goes to the tech lead and the system owner. If a required system has no way in at all, that stops the work, and you record why." },
          { title: "Record owners and follow-ups", text: "For every unknown or high-risk row, draft the follow-up: who to ask, the exact question, and how the answer should come back — in writing, with a date. Add each one to the question log. Every open item has a name on it." },
        ] },
        { t: "figure", fig: { kind: "tree", root: "One integration row (INT-##)", children: [{ label: "Direction", children: [{ label: "In" }, { label: "Out" }, { label: "Both" }] }, { label: "Interface type", children: [{ label: "REST, SOAP, file, database" }, { label: "Email, queue, manual" }] }, { label: "Auth and owner", text: "Auth method, who issues credentials, who owns it" }, { label: "Limits", children: [{ label: "Rate" }, { label: "Payload size" }, { label: "Timeout" }, { label: "Opening hours" }] }, { label: "Errors", children: [{ label: "Error responses" }, { label: "Idempotency" }, { label: "Versioning" }] }, { label: "Proof", text: "One real test call in a test environment — request and response kept" }] }, caption: "What one inventory row holds once steps 2 and 3 are done. Any branch you can’t fill says “unknown” and has a question behind it." },
        { t: "figure", fig: { kind: "workflow", fid: "discover.context.integrations" }, caption: "Map Data, Integrations & Dependencies — trace, list, test, decide, record. Missing limits loop back to the contract review; a blocking dependency goes to its system owner." },
        { t: "callout", tone: "warn", title: "Never test against production", text: "Test calls go to a test tenant or sandbox. If there isn’t one, that’s a finding — and a question for the system owner. If a call does reach production by mistake, stop, report it, and repeat it in a test environment." },
        { t: "figure", fig: { kind: "decide", start: "sandbox", nodes: [{ id: "sandbox", q: "Is there a test tenant or sandbox?", yes: "call", no: "finding" }, { id: "finding", result: "That’s a finding — and a question for the system owner", tone: "neutral" }, { id: "call", q: "Did the call reach production by mistake?", yes: "stop", no: "keep" }, { id: "stop", result: "Stop, report it, and repeat it in a test environment", tone: "bad" }, { id: "keep", result: "Keep the request and response as evidence", tone: "good" }] }, caption: "The test-call rule as a walk-through. No path ends with a call against production being accepted." },
        { t: "p", text: "Two things deserve special care. **Personal data** must be flagged wherever it flows — it brings constraints of its own, and the client’s data-protection policy governs how you handle it. And when there is **no API at all** — only a file drop or a database link — record it and mark it high risk." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "The engineer follows the data. Orders arrive as PDFs in a Microsoft 365 shared inbox, and the clerks re-type each line into the ERP and email a confirmation. That re-typing is **DF-02 — manual**: the flow the whole brief is about, and one that appears in no system diagram because a person does it." },
        { t: "figure", fig: { kind: "flow", steps: [
          { label: "Customer", sub: "Sends email + PDF", tone: "human" },
          { label: "Shared inbox", sub: "Microsoft 365", tone: "system" },
          { label: "Order clerk", sub: "Re-types each line (DF-02, manual)", tone: "risk" },
          { label: "ERP v9", sub: "Sales order", tone: "system" },
          { label: "Customer", sub: "Confirmation email", tone: "human" },
        ] }, caption: "Northwind’s order flow today. The step that matters most is a person carrying the data by hand — DF-02." },
        { t: "p", text: "The ERP takes orders only through its **REST import API** — 500 lines a request, authenticated with an API key per tenant, documented in the ERP admin guide §7. Its rate limit isn’t documented, so the engineer writes **unknown** and asks the ERP admin in writing." },
        { t: "table", caption: "Northwind’s integration inventory (from the template’s example)", head: ["ID", "System", "Dir.", "Interface", "Auth", "Limits", "Owner", "Risk"], rows: [
          ["INT-01", "ERP v9 import API", "Out", "REST API", "API key per tenant", "Unknown rate limit; 500 lines per request", "ERP admin", "High"],
          ["INT-02", "Microsoft 365 shared inbox", "In", "REST API", "OAuth 2.0 app registration", "Graph throttling 10k requests / 10 min", "IT", "Low"],
          ["INT-03", "PDF parsing / OCR (to choose)", "Both", "REST API", "—", "Accuracy on poor scans unknown", "Tech lead", "High"],
        ] },
        { t: "figure", fig: { kind: "context", center: { label: "The solution", sub: "nothing chosen yet" }, around: [{ label: "INT-01 ERP v9 import API", sub: "Owner: ERP admin · High risk", type: "system", dir: "out", link: "REST API · API key per tenant", text: "Unknown rate limit; 500 lines per request." }, { label: "INT-02 Microsoft 365 shared inbox", sub: "Owner: IT · Low risk", type: "external", dir: "in", link: "REST API · OAuth 2.0 app registration", text: "Graph throttling 10k requests / 10 min." }, { label: "INT-03 PDF parsing / OCR", sub: "To choose · Owner: tech lead · High risk", type: "external", dir: "both", link: "REST API", text: "Accuracy on poor scans unknown." }] }, caption: "Northwind’s three integrations around a solution not yet designed. Two of the three are high risk, and both for the same reason: a limit nobody knows yet." },
        { t: "p", text: "Look at INT-01’s limits next to the brief. Orders run from 1 to 40 lines, so a single order fits well inside 500 lines a request — that limit is unlikely to bite. The unknown rate limit is a different matter: with volumes doubling at peak, it could. That is why INT-01 is marked high risk and why the question goes in writing." },
        { t: "figure", fig: { kind: "bars", unit: "lines per request", rows: [{ label: "Largest order", value: 40, max: 500, tone: "good", note: "Orders run from 1 to 40 lines" }, { label: "ERP import API limit", value: 500, max: 500, tone: "neutral", note: "ERP admin guide §7" }] }, caption: "A single order fits well inside the payload limit, so that limit is unlikely to bite. The risk is the rate limit, which has no bar because nobody knows it yet." },
        { t: "p", text: "INT-03 is there even though nothing has been chosen. Reading PDFs is capability 2, and whatever does it will be a dependency — with its own limits, its own auth and, because order PDFs carry customer data, its own privacy questions. Listing it now, as “to choose”, keeps it from appearing as a surprise later." },
        { t: "figure", fig: { kind: "template", id: "integration-inventory" }, caption: "The integration inventory — interface, auth, limits, contract, owner and risk for every dependency, including ones still to be chosen." },
        { t: "contrast", label: "Writing down a limit", bad: { title: "Borrowed", text: "“Rate limit: about 100 requests a minute (typical for this kind of API).” Copied from somewhere else, untested, and now indistinguishable from a fact." }, good: { title: "Honest", text: "“Rate limit: unknown — asked the ERP admin in writing, answer due by [date]. Payload: 500 lines per request (ERP admin guide §7).”" } },
        { t: "contrast", label: "Proving an integration", bad: { title: "Read about", text: "“The inbox can be read through Microsoft Graph — it’s well documented.”" }, good: { title: "Called", text: "“Test call to the shared inbox in the test tenant: request and response saved; auth via the OAuth 2.0 app registration worked; throttling limit taken from the Microsoft Graph docs.”" } },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "The agent finds the integrations; only a real call tells you their limits. Agents are good at scanning a codebase for outbound calls, queues, file drops and credentials, and at reading long API documents. They are bad at saying “I don’t know” — ask them to, explicitly." },
        { t: "prompt", title: "Trace the flows and list the dependencies", text: "Using the system audit and context diagram I’ve pasted, and the repository I’ve given you read access to:\n1. Trace the data through today’s flow, as rows for my data flow map: DF-## ID, from, to, what data, format, trigger or frequency, volume, sensitivity (public / internal / personal / confidential), and whether a person does it by hand.\n2. Scan the code for every outbound call, queue, file drop and credential, and list every system, API and service the solution will depend on as inventory rows: INT-## ID, direction, interface type, auth method, owner. Include ones we’d have to add.\nWhere you don’t know a value, write ‘unknown’. Do not estimate volumes or limits." },
        { t: "p", text: "Check: are the manual flows there — the ones a person does? Agents reading code won’t see them; add them from what you saw. Is every flow carrying personal data flagged? Did any volume or limit appear that you can’t trace to a document or a measurement?" },
        { t: "prompt", title: "Review each contract and draft a test call", text: "For each integration in my inventory, read its real contract (OpenAPI spec, vendor guide or the calling code) and fill in: limits (rate, payload size, timeout, opening hours), error responses, idempotency and versioning. Cite the section for every value. Write ‘unknown’ instead of guessing. Then give me a single test call I can run against a test environment for each — never production — and, for every unknown, draft the written question to its owner." },
        { t: "p", text: "Check: does every limit have a citation you can open? Does every test call point at a test tenant or sandbox, not a production URL? Then make the calls yourself, record the responses, and correct the rows." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent"], steps: [{ lane: 1, label: "Trace flows as DF rows", sub: "“unknown” where it doesn’t know" }, { lane: 1, label: "Scan the code; draft INT rows" }, { lane: 0, label: "Add the manual flows", sub: "Agents reading code won’t see them", flag: "manual" }, { lane: 0, label: "Check personal-data flags and sources" }, { lane: 1, label: "Read contracts; cite limits; draft test calls" }, { lane: 0, label: "Make the test calls in a test environment" }, { lane: 0, label: "Correct the rows", flag: "ok" }] }, caption: "The agent finds the integrations; you add what it can’t see and prove what it read. The last three steps are always yours." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Ask your agent to scan the codebase for every outbound call, queue, file drop and credential, and draft an inventory row for each. Then make the test calls yourself and correct the rows — the agent finds the integrations; only a real call tells you their limits." },

        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "Limits copied from a different API.", fix: "Mark the limit unknown and ask the owner in writing, with a date." },
          { trap: "A test call made against production.", fix: "Stop, report it, and repeat it in a test environment." },
          { trap: "Only flows that software performs are traced.", fix: "Watch the work. Re-typing, copying between spreadsheets and forwarding emails are flows too." },
          { trap: "Personal data noted once, not everywhere it flows.", fix: "Flag sensitivity on every DF row, and follow personal data to every store and service." },
          { trap: "Undocumented API treated as a dead end.", fix: "Read the code that calls it today and log the contract you infer, marked as inferred." },
          { trap: "Integrations still to be chosen are left off.", fix: "List them as “to choose” with their unknowns. They’re dependencies whether you’ve picked them or not." },
        ] },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of 1.1.3", head: ["Situation", "What you do"], rows: [
          ["Limits or owners missing", "Rework — back to the contract review"],
          ["Vendor won’t share limits", "Log them as unknown and ask in writing"],
          ["Undocumented API", "Read the calling code and log the contract you infer"],
          ["No API — a file drop or database link", "Record it and mark it high risk"],
          ["Single integration", "A one-row inventory — still with limits"],
          ["Blocking dependency (no access, no API)", "Escalate to the tech lead and the system owner"],
          ["Unsourced integration limit reaches 1.1.4", "Back here to source it"],
          ["A required system has no way in at all", "Stop and record it — recorded in the learning log"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "way", nodes: [{ id: "way", q: "Does the required system have any way in?", yes: "api", no: "stop" }, { id: "stop", result: "Stop and record it — recorded in the learning log", tone: "bad" }, { id: "api", q: "Is there an API?", yes: "access", no: "file" }, { id: "file", result: "File drop or database link: record it and mark it high risk", tone: "neutral" }, { id: "access", q: "Is the dependency blocked (no access)?", yes: "esc", no: "doc" }, { id: "esc", result: "Escalate to the tech lead and the system owner", tone: "bad" }, { id: "doc", q: "Is the API documented?", yes: "lim", no: "infer" }, { id: "infer", result: "Read the calling code and log the contract you infer", tone: "neutral" }, { id: "lim", q: "Are limits and owners all filled in?", yes: "ok", no: "rework" }, { id: "rework", result: "Rework — back to the contract review; if the vendor won’t share, log unknown and ask in writing", tone: "neutral" }, { id: "ok", result: "The map and inventory go on to 1.1.4", tone: "good" }] }, caption: "The routes out of 1.1.3. Only “no way in at all” stops the work; every other gap has a way forward and a person who owns it." },

        { t: "h", text: "What good looks like" },
        { t: "p", text: "A good map lets someone who has never seen the system say where every piece of data comes from, where it goes, who touches it by hand and what could stop it. A good inventory has no blank cells — only values with sources, and unknowns with questions attached. Limits that surprised the team later go in the learning log." },
        { t: "good", items: ["Every flow has format, frequency and volume", "Every integration has interface, auth, limits and owner", "Personal data is flagged wherever it flows", "Each integration was proven with a test call"] },
        { t: "checklist", title: "Before you move on", items: [
          "Every flow has a DF-## ID, format, frequency, volume and sensitivity",
          "Manual flows — re-typing, copying — are on the map",
          "Personal data is flagged on every flow that carries it",
          "Every integration has an INT-## ID, interface, auth, limits and owner",
          "Every limit cites its source or says unknown",
          "Each integration was proven with one test call — in a test environment",
          "Every unknown has a written question with an owner and a date",
          "The tech lead knows whether any dependency is blocking",
        ] },
        { t: "try", text: "Fill two integration inventory rows for the order-intake case — the ERP import API and the shared inbox — with interface, auth, limits and owner. Then do the same for your own project." },
      ],
    },

    /* ───────────────────────────── 1.1.4 ───────────────────────────── */
    {
      id: "discover.context.constraints", fid: "discover.context.constraints", code: "1.1.4", title: "Log Technical Constraints & Assumptions", minutes: 13,
      blocks: [
        { t: "lead", text: "By now you know a lot — and you’re also assuming a lot, often without noticing which is which. This lesson pulls every limit into one log, separates what you know from what you’re assuming, and hands on one consolidated technical picture: the system context pack." },
        { t: "tldr", items: [
          "Pull every limit from the topic’s documents into one log, each with an ID and a source.",
          "A constraint has a source you could show someone; anything else is an assumption.",
          "Every assumption gets a confidence and the cheapest test that could prove it wrong.",
          "Hard constraints are confirmed in writing by their owners.",
          "Assemble the system context pack — and stopping because it’s impossible is a valid result.",
        ] },
        { t: "p", text: "The job: *help me know which limits are real and which are guesses I still have to test.* The rule that runs through the whole lesson: **assumptions are never presented as facts.**" },

        { t: "h", text: "Why it matters" },
        { t: "p", text: "Two concerns. **Guesses designed around as facts** — a design built on “most PDFs are generated” works beautifully until the first week of scans. And **constraints found late** — a data-residency rule discovered after a service has been chosen means choosing again." },
        { t: "p", text: "The two failures have the same cause: a statement in a document with nothing to say how sure anyone is. The log fixes that by giving every statement a kind (constraint or assumption), a source, and — for assumptions — a confidence and a test. Topic 1.2 turns the riskiest assumptions into hypotheses and spikes; it can only do that if they’re labelled here." },
        { t: "figure", fig: { kind: "hub", center: "Every statement in the log", items: [{ label: "Kind", icon: "category", text: "Constraint or assumption." }, { label: "Source", icon: "link", text: "Where it came from — something you could show someone." }, { label: "Confidence", icon: "adjust", text: "For assumptions: high, medium or low." }, { label: "Test", icon: "science", text: "For assumptions: the cheapest way to find out it’s wrong." }] }, caption: "What the log adds to every statement so nobody has to guess how sure anyone is. Topic 1.2 can only pick up assumptions labelled this way." },
        { t: "pull", text: "Facts are sourced. Guesses are labelled. Never mixed." },

        { t: "h", text: "Where it sits in Discover" },
        { t: "p", text: "This lesson closes topic 1.1. It takes everything the topic has produced — the technical brief summary, the system audit, the data flow map, the integration inventory and the question log — and produces the **technical constraint log** and the **system context pack**. The pack goes to 1.2, Frame the Technical Problem, and it is what the System Context Review accepts or sends back." },
        { t: "figure", fig: { kind: "funnel", stages: [{ label: "The topic’s documents", items: ["Technical brief summary", "System audit", "Data flow map", "Integration inventory", "Technical question log"] }, { label: "Technical constraint log", items: ["C-## constraints", "A-## assumptions"] }, { label: "System context pack", items: ["Goes to 1.2, Frame the Technical Problem"] }, { label: "System Context Review", items: ["Accepted or sent back"] }] }, caption: "How the whole topic narrows into one hand-over. Five documents become one log and one pack, and the review decides whether it moves on." },
        { t: "p", text: "It creates the last links of topic 1.1’s trace chain: C-## for each constraint and A-## for each assumption, each linked to where it came from and to the request." },

        { t: "h", text: "What you start with" },
        { t: "table", caption: "Inputs and outputs", head: ["In", "Out"], rows: [
          ["Technical brief summary", "Technical constraint log — C-## and A-## rows"],
          ["System audit", "System context pack — the topic’s outputs in one place"],
          ["Data flow map", "Constraint owner confirmations (evidence)"],
          ["Integration inventory", ""],
          ["Technical question log", ""],
        ] },
        { t: "table", caption: "Who does what in 1.1.4 (RACI)", head: ["Role", "RACI", "What they do here"], rows: [
          ["Engineer", "R — Responsible", "Builds the log, tags assumptions, gets confirmations, assembles the pack"],
          ["Tech lead", "A — Accountable", "Accepts the pack at the System Context Review"],
          ["Architect", "C — Consulted", "Challenges which limits are really hard"],
          ["Privacy officer", "C — Consulted", "Confirms data and regulatory constraints"],
          ["Client contact", "I — Informed", "Hears what was found — and any conflict with the ask"],
        ] },
        { t: "p", text: "The timebox is two to four hours. The slow part is usually owners’ availability, so send confirmation requests early and let them run while you assemble the pack." },

        { t: "h", text: "Key ideas" },
        { t: "h3", text: "Constraint or assumption" },
        { t: "p", text: "A **constraint** is a limit you can source: a document, a policy, a test call, an owner who confirmed it. An **assumption** is something you believe but can’t yet show. The test is blunt: could you show someone where it came from? If not, it’s an assumption — however confident you feel and however senior the person who said it in passing." },
        { t: "figure", fig: { kind: "split", left: { title: "Constraints — facts", tone: "fact", items: ["Have a source you can point at", "Are confirmed by their owner", "Are hard (can’t move) or soft (a preference)"] }, right: { title: "Assumptions — guesses", tone: "guess", items: ["Have a confidence: high, medium or low", "Have a test that would prove them wrong", "Are never presented as facts"] } }, caption: "Two columns, never mixed. A constraint you can’t source is an assumption until someone confirms it." },
        { t: "figure", fig: { kind: "knowledge", name: "Facts are sourced, guesses are labelled" }, caption: "The principle in practice: a limit with its source, an assumption with its confidence and test — and the vague statements to avoid." },
        { t: "h3", text: "Hard or soft" },
        { t: "p", text: "Constraints come in two strengths. A **hard** constraint can’t move: a regulation, the only interface a vendor system offers, a contract. A **soft** constraint is a preference — “we’d rather stay on our current cloud” — real, and worth respecting, but negotiable. When a “constraint” turns out to be a preference, don’t delete it; reclassify it as soft." },
        { t: "figure", fig: { kind: "decide", start: "src", nodes: [{ id: "src", q: "Could you show someone where it came from?", yes: "move", no: "assume" }, { id: "assume", result: "Assumption — give it a confidence and the cheapest test", tone: "neutral" }, { id: "move", q: "Is it really a preference that could move?", yes: "soft", no: "hard" }, { id: "soft", result: "Soft constraint — respected, recorded, negotiable", tone: "neutral" }, { id: "hard", result: "Hard constraint — confirm it in writing with its owner", tone: "good" }] }, caption: "Sorting any statement in two questions. Seniority and confidence don’t appear anywhere — only whether a source exists and whether the limit can move." },
        { t: "h3", text: "Confidence and the cheapest test" },
        { t: "p", text: "Every assumption carries a confidence — high, medium or low — and the cheapest way to find out whether it’s wrong. Cheap matters. Counting a sample of real inputs, reading one config file or asking one person in writing is usually enough; a spike is for what those can’t answer." },
        { t: "figure", fig: { kind: "stack", layers: [{ label: "Count a sample of real inputs", sub: "Cheap" }, { label: "Read one config file", sub: "Cheap" }, { label: "Ask one person in writing", sub: "Cheap" }, { label: "A spike", sub: "For what those can’t answer" }] }, caption: "Tests for an assumption, cheapest first. Most assumptions are settled by one of the top three; a spike is the last resort, not the first." },
        { t: "h3", text: "Mapping assumptions by risk" },
        { t: "p", text: "Not every assumption needs testing now. An **assumption map** plots each one by how important it is against how much evidence you have. Important and unevidenced: test first. Important and evidenced: proceed and watch. Less important: defer or ignore. This is the bridge to topic 1.2, where the top-left corner becomes hypotheses and spikes." },
        { t: "figure", fig: { kind: "knowledge", name: "Assumption map" }, caption: "The assumption map: what you’d lose if a guess were wrong, against how sure you are of it. The important, unevidenced corner gets tested first." },
        { t: "h3", text: "Constraints in the architecture record" },
        { t: "p", text: "arc42, a widely used template for documenting architecture, gives constraints their own section — technical, organisational and regulatory limits that any solution must respect — right after introduction and goals. The log you build here is that section’s raw material. ISO/IEC 25010’s quality characteristics are a useful checklist when you sweep for limits: performance, compatibility, security, maintainability and the rest." },
        { t: "terms", items: [
          { term: "Constraint (C-##)", def: "A limit on any solution, with a source you could show someone. Hard or soft." },
          { term: "Assumption (A-##)", def: "Something you believe but can’t source yet, with a confidence and a test that would prove it wrong." },
          { term: "Hard constraint", def: "A limit that can’t move — regulation, a vendor’s only interface, a contract. Confirmed in writing by its owner." },
          { term: "Soft constraint", def: "A preference. Respected, recorded, but negotiable." },
          { term: "Confidence", def: "High, medium or low — how sure you are of an assumption, and therefore how urgently it needs a test." },
          { term: "System context pack", def: "The topic’s outputs together: brief summary, audit, context diagram, data flows, integrations, constraints and open questions." },
        ] },

        { t: "h", text: "How to do it" },
        { t: "steps", items: [
          { title: "Pull every limit into the log", text: "Go back through the brief summary, the audit, the data flow map and the integration inventory. Every limit you found becomes a row: an ID (C-## or A-##), the statement, its area (integration, data, security, infrastructure, performance, code), hard or soft, and the source. Look beyond the brief — the audit and the integrations usually hold more limits than the client mentioned: hosting, region, platform, payload sizes, rate limits. Add nothing that isn’t in your documents.", tip: "Read each integration row’s “limits” column and each audit verdict line. Most of your constraints are sitting there already." },
          { title: "Tag the assumptions and how to test them", text: "Challenge every row: does it have a source you could show someone? Anything that doesn’t is re-tagged as an assumption, with a confidence — high, medium or low — and the cheapest way to test it. A verbal comment from a colleague is a lead, not a source: it makes a low-confidence assumption until someone confirms it." },
          { title: "Confirm the hard constraints with their owners", text: "For each hard constraint, send its owner a short confirmation request: the statement, its source, and a yes/no question — so you get it confirmed in writing. Data and regulatory constraints are confirmed by the privacy officer or compliance. A hard constraint that hasn’t been confirmed is a risk you’re choosing not to see. If an owner is unreachable, keep it as a low-confidence assumption until they answer.", tip: "A yes/no question gets answered. “Can you review our constraints?” gets put off." },
          { title: "Assemble the system context pack", text: "Put the topic together: one paragraph per part — brief, audit, context diagram, data flows, integrations, constraints, open questions — each linked to the full document, and a short “what this means for the next step” at the end. Carry the volume and latency limits into the pack explicitly; they’re what the next lessons will measure against. Owner confirmations can still be arriving while you assemble." },
          { title: "Decide: is the pack accepted?", text: "Review it as the tech lead would: could someone frame the problem from this pack without guessing? Unsourced entries go back to the log. If hard constraints conflict with the ask, the tech lead takes it to the client. If a hard constraint makes the ask impossible, stop and record why — that is a successful discovery, not a failed one." },
        ] },
        { t: "figure", fig: { kind: "lanes", lanes: ["Engineer", "Owners", "Privacy / compliance", "Tech lead"], steps: [{ lane: 0, label: "Pull every limit into the log" }, { lane: 0, label: "Tag assumptions with confidence and test" }, { lane: 0, label: "Send yes/no confirmation requests", flag: "wait" }, { lane: 1, label: "Confirm hard constraints in writing", flag: "ok" }, { lane: 2, label: "Confirm data and regulatory constraints", flag: "ok" }, { lane: 0, label: "Assemble the system context pack", sub: "While confirmations arrive" }, { lane: 3, label: "Accept the pack — or send it back", sub: "System Context Review" }] }, caption: "Who does what in 1.1.4. The wait for owners runs in parallel with assembling the pack, so send the requests early." },
        { t: "figure", fig: { kind: "workflow", fid: "discover.context.constraints" }, caption: "Log Technical Constraints & Assumptions — pull, tag, confirm, assemble, accept. Unsourced entries loop back to the log; conflicts go to the client; impossibility stops the work, on the record." },
        { t: "callout", tone: "tip", title: "A constraint that’s really a preference", text: "When a “constraint” turns out to be someone’s preference, don’t delete it — reclassify it as soft. And if hard constraints make the ask impossible, stop and record why. That is a successful discovery, not a failed one." },

        { t: "h", text: "The case: Northwind" },
        { t: "p", text: "The engineer pulls the topic’s limits into one log. Two are hard and sourced; one important belief turns out to have no source at all." },
        { t: "table", caption: "Northwind’s constraint and assumption log (from the template’s example)", head: ["ID", "Statement", "Kind", "Hard / soft", "Source", "Confidence", "How we’d test it", "Owner"], rows: [
          ["C-01", "Orders enter the ERP only through its REST import API", "Constraint", "Hard", "ERP admin guide §7; ERP admin", "High", "—", "ERP admin"],
          ["C-02", "Customer data stays in the EU", "Constraint", "Hard", "Client brief; data-protection policy", "High", "—", "Privacy officer"],
          ["A-01", "80% of order PDFs are machine-generated, not scans", "Assumption", "Soft", "Order-clerk lead, verbally", "Low", "Classify a 2-week inbox sample", "Engineer"],
        ] },
        { t: "p", text: "C-01 and C-02 are confirmed by their owners: the ERP admin for the import API, the privacy officer for EU data. Both will shape every option in topic 1.4 — the first rules out writing to the ERP’s database or screens, the second rules out any service that keeps customer data outside the EU." },
        { t: "figure", fig: { kind: "tree", root: "Hard constraints that shape topic 1.4", children: [{ label: "C-01 Import API only", text: "Confirmed by the ERP admin", children: [{ label: "Rules out writing to the ERP’s database or screens" }] }, { label: "C-02 Customer data in the EU", text: "Confirmed by the privacy officer", children: [{ label: "Rules out any service keeping customer data outside the EU" }] }] }, caption: "Northwind’s two hard constraints, who confirmed each, and what each rules out. Every option in topic 1.4 has to pass both." },
        { t: "p", text: "A-01 is the interesting one. It came from the order-clerk lead, verbally — a useful lead from someone who knows the inbox, but not a source you could show anyone. So it’s an assumption, with **low** confidence, and a cheap test: classify a two-week inbox sample. It also links straight back to Q-02 (“What share of PDFs are scans vs generated?”), which was marked as needing a spike. It matters because scans need OCR, and that is an accuracy risk." },
        { t: "figure", fig: { kind: "anatomy", parts: [{ text: "A-01", label: "ID" }, { text: ", low confidence", label: "Confidence" }, { text: ": 80% of order PDFs are machine-generated, not scans.", label: "Statement" }, { text: " Source: order-clerk lead, verbally.", label: "Source", note: "A lead, not a source you could show anyone — so it stays an assumption." }, { text: " Test: classify a 2-week inbox sample.", label: "Test", note: "Links back to Q-02." }, { text: " Owner: engineer.", label: "Owner" }] }, caption: "Northwind’s A-01, taken apart. The confidence comes first, so nobody can read the statement as a fact." },
        { t: "figure", fig: { kind: "matrix", x: "Evidence we have →", y: "Importance ↑", hot: "tl", hotLabel: "Test these first", points: [
          { label: "C-01 import API only", x: 0.85, y: 0.9 },
          { label: "C-02 EU data", x: 0.8, y: 0.8 },
          { label: "A-01 most PDFs generated", x: 0.15, y: 0.85 },
        ] }, caption: "Northwind’s log on an assumption map. The two constraints are important and sourced; A-01 is important with almost no evidence — the corner that gets tested first." },
        { t: "p", text: "The engineer assembles the system context pack — brief, audit, context diagram, data flows, integrations, constraints and open questions — and the tech lead accepts it at the System Context Review." },
        { t: "figure", fig: { kind: "template", id: "technical-constraint-log" }, caption: "The technical constraint & assumption log — kind, area, hard or soft, source, confidence, test and owner for every limit." },
        { t: "figure", fig: { kind: "template", id: "system-context-pack" }, caption: "The system context pack — the seven parts of topic 1.1 in one place, each with what it tells the next step. This is what goes to 1.2." },
        { t: "contrast", label: "Writing down a belief", bad: { title: "Presented as fact", text: "“Most orders are generated PDFs, so text extraction will be straightforward.” No source, no confidence — and a design conclusion already drawn from it." }, good: { title: "Labelled as a guess", text: "“A-01, low confidence: 80% of order PDFs are machine-generated, not scans. Source: order-clerk lead, verbally. Test: classify a 2-week inbox sample. Owner: engineer.”" } },
        { t: "contrast", label: "Handling a preference", bad: { title: "Deleted or obeyed", text: "The client “prefers” a particular cloud provider. Either it disappears from the log, or it’s written as a hard constraint and quietly rules out every other option." }, good: { title: "Reclassified", text: "Logged as a soft constraint, with its source. If an owner later confirms it’s required, it becomes hard — with that confirmation as its source." } },

        { t: "h", text: "Working with your agent" },
        { t: "p", text: "Consolidating is where an agent saves real time: it can read all four documents at once and pull out every limit with the line it came from. Watch for one failure above all: agents state assumptions confidently. A fluent sentence is not a source." },
        { t: "prompt", title: "Pull and challenge every limit", text: "From my technical brief summary, system audit, data flow map and integration inventory (pasted below), pull out every technical limit as constraint-log rows: C-## or A-## ID, the statement, area, hard or soft, and the source — quoting the line it came from.\nDon’t add anything that isn’t in my documents.\nThen challenge each row: does it have a source I could show someone? Re-tag anything that doesn’t as an assumption, with a confidence (high / medium / low) and the cheapest way to test it." },
        { t: "p", text: "Check: open the quoted line for every constraint — does it say what the row says? Is anything in the log that isn’t in your documents? Did any verbal or second-hand statement survive as a constraint? Every unsourced line must end up in the assumptions column." },
        { t: "prompt", title: "Confirm, assemble and review the pack", text: "For each hard constraint in my log, write a short confirmation request to its owner — the statement, its source, and a yes/no question.\nThen assemble my system context pack: one paragraph per part (brief, audit, context diagram, data flows, integrations, constraints, open questions) with a link to the full document, and a short ‘what this means for the next step’.\nFinally, review the pack as the tech lead would: could someone frame the problem from it without guessing? List what’s missing or unsourced." },
        { t: "p", text: "Check: did the pack’s summaries add any claim that isn’t in the underlying documents? Are the volume and latency limits carried through? The agent’s review is a rehearsal — the tech lead’s acceptance is the decision, and owners’ written confirmations are the evidence." },
        { t: "figure", fig: { kind: "lanes", lanes: ["You", "Agent", "Owners", "Tech lead"], steps: [{ lane: 1, label: "Pull every limit, quoting its line" }, { lane: 0, label: "Open each quoted line" }, { lane: 1, label: "Re-tag unsourced rows as assumptions" }, { lane: 1, label: "Draft confirmations; assemble the pack", sub: "Rehearses the review" }, { lane: 2, label: "Confirm in writing", flag: "ok" }, { lane: 3, label: "Accepts the pack", flag: "ok" }] }, caption: "The agent consolidates and rehearses; owners and the tech lead decide. Your one job in the middle is to check every quoted line." },
        { t: "callout", tone: "agent", title: "With your agent", text: "Give your agent all four artifacts from this topic and ask it to extract every limit, each with the line it came from, and to flag anything it can’t source as an assumption. Watch for one failure: agents state assumptions confidently. Every unsourced line must end up in the assumptions column." },

        { t: "h", text: "Common mistakes" },
        { t: "pitfalls", items: [
          { trap: "An assumption written as a fact.", fix: "Re-tag it with a confidence and a test. If you can’t show the source, it’s an assumption." },
          { trap: "A hard constraint never confirmed.", fix: "Keep it as an assumption until its owner confirms it in writing." },
          { trap: "Only the client’s limits are logged.", fix: "Sweep the audit and the integration inventory too — hosting, region, payload sizes, rate limits." },
          { trap: "A preference treated as hard.", fix: "Reclassify it as soft. Only a confirmed limit is hard." },
          { trap: "Assumptions without a test.", fix: "Give each the cheapest test that could prove it wrong — often a sample, a document or one written question." },
          { trap: "The pack is a pile of attachments.", fix: "One paragraph per part and a “what this means for the next step”, so someone can frame the problem without guessing." },
        ] },

        { t: "h", text: "When it goes off the path" },
        { t: "table", caption: "Routes out of 1.1.4", head: ["Situation", "What you do"], rows: [
          ["Unsourced entries", "Rework — back to the log"],
          ["A “constraint” turns out to be a preference", "Reclassify it as soft"],
          ["Owner unreachable", "Keep it as a low-confidence assumption"],
          ["Regulated data", "Privacy or compliance confirms the data constraints"],
          ["Small change", "Log and pack in one sheet"],
          ["Hard constraints conflict with the ask", "Escalate — the tech lead takes it to the client"],
          ["A hard constraint makes the ask impossible", "Stop and record why — recorded in the learning log"],
        ] },
        { t: "figure", fig: { kind: "decide", start: "src", nodes: [{ id: "src", q: "Does every entry have a source?", yes: "pref", no: "rework" }, { id: "rework", result: "Rework — back to the log", tone: "bad" }, { id: "pref", q: "Has a “constraint” turned out to be a preference?", yes: "soft", no: "owner" }, { id: "soft", result: "Reclassify it as soft", tone: "neutral" }, { id: "owner", q: "Is a hard constraint’s owner unreachable?", yes: "low", no: "conf" }, { id: "low", result: "Keep it as a low-confidence assumption", tone: "neutral" }, { id: "conf", q: "Do hard constraints conflict with the ask?", yes: "imp", no: "ok" }, { id: "imp", q: "Does a hard constraint make the ask impossible?", yes: "stop", no: "esc" }, { id: "stop", result: "Stop and record why — a successful discovery, in the learning log", tone: "neutral" }, { id: "esc", result: "Escalate — the tech lead takes it to the client", tone: "neutral" }, { id: "ok", result: "The pack goes to the System Context Review", tone: "good" }] }, caption: "The routes out of 1.1.4. A conflict goes to the client through the tech lead; an impossibility stops the work, on the record." },
        { t: "note", text: "Assumptions that turn out wrong later go in the learning log. Over a few projects, that log tells you which kinds of guesses your team gets wrong most often." },

        { t: "h", text: "What good looks like" },
        { t: "p", text: "A good log has two clean columns: facts with sources, guesses with confidences and tests. Nobody reading it could mistake one for the other. A good pack is short enough to read in one sitting and complete enough that the next lesson starts without a single “I think”." },
        { t: "good", items: ["Constraints and assumptions are kept apart", "Every entry has a source", "Every assumption has a confidence and a test", "Hard constraints are confirmed by their owners"] },
        { t: "checklist", title: "Before you move on", items: [
          "Every limit from the brief, audit, flows and integrations is in the log",
          "Every entry has a C-## or A-## ID and a source",
          "Every constraint is marked hard or soft",
          "Every assumption has a confidence and the cheapest test",
          "Hard constraints are confirmed in writing by their owners",
          "Data and regulatory constraints are confirmed by privacy or compliance",
          "The pack has one paragraph per part and a “what this means next”",
          "The tech lead has accepted the pack at the System Context Review",
        ] },
        { t: "try", text: "Write two constraints and two assumptions for the order-intake case, each with its source, and a test for each assumption. Then do the same for your own project." },
      ],
    },
  ],
};
